const config = loadNoShowConfig($env);
const calendly = nodeOutputs("Tag Calendly Responses");
assertStageComplete('Calendly lookup', countPlanned("Plan Calendly Invitee Lookups"), calendly.length);
const events = applyCalendlyLookups(firstOutput("Load Config & Route").events, calendly);
return planItems('lookups', planPrimaryLookups(events, config));

