  if (!isPlaceholder(config.webhook.secret) && config.webhook.secret.length < MIN_SECRET_LENGTH) errors.push(`WEBHOOK_SECRET must be at least ${MIN_SECRET_LENGTH} characters`);
  if (!isPlaceholder(config.hubspot.sandboxPortalId) && !/^\d+$/.test(config.hubspot.sandboxPortalId)) errors.push('HUBSPOT_SANDBOX_PORTAL_ID must be numeric when set');
  if (!Object.keys(config.deals.stageMap).length) warnings.push('NO_SHOW_DEAL_STAGE_MAP is empty, so deal stages are never changed.');
  if (hasCalendly && isPlaceholder(config.calendly.apiToken)) warnings.push('CALENDLY_API_TOKEN is not set; Calendly no-show events without an invitee email in the payload are skipped.');
  if (config.email.provider === 'none' && !smsEnabled(config)) warnings.push('Both EMAIL_PROVIDER and SMS_PROVIDER are none: only rep tasks are created.');
  if (live && !alertsEnabled(config)) warnings.push('Live mode without ALERT_WEBHOOK_URL: failures are only visible in the n8n execution log.');
  return { errors, warnings };
}

// ---- src/core/hubspot.js (embedded by scripts/build-workflow.js) ----
/**
 * HubSpot and Calendly request builders and parsers. No network access, and no request object
 * carries a token: the n8n HTTP Request nodes add Authorization headers from $env.
 */

const ASSOCIATION_TYPES = Object.freeze({ taskToContact: 204, taskToDeal: 216 });
const MEETING_PROPERTIES = Object.freeze(['hs_meeting_outcome', 'hs_meeting_title', 'hs_meeting_start_time', 'hubspot_owner_id']);
const DEAL_PROPERTIES = Object.freeze(['dealname', 'dealstage', 'pipeline', 'hubspot_owner_id', 'createdate', 'amount']);

function contactProperties(config) {
  return [...new Set(['email', 'firstname', 'lastname', 'mobilephone', 'phone', 'hubspot_owner_id', config.routing.smsConsentProperty, config.routing.emailOptOutProperty, ...Object.values(config.properties)])];
}

function hubspotUrl(config, path) {
  return `${config.hubspot.baseUrl}${path}`;
}

const buildAccountDetailsRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/account-info/v3/details') });
const buildPipelinesRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/crm/v3/pipelines/deals') });
const buildOwnersRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/crm/v3/owners?limit=500&archived=false') });

function buildMeetingReadRequest(config, meetingId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/meetings/${encodeURIComponent(meetingId)}?properties=${encodeURIComponent(MEETING_PROPERTIES.join(','))}&associations=contacts,deals`) };
}

function buildContactReadRequest(config, contactId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}?properties=${encodeURIComponent(contactProperties(config).join(','))}&associations=deals`) };
}

function buildContactByEmailRequest(config, email) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(email)}?idProperty=email&properties=${encodeURIComponent(contactProperties(config).join(','))}&associations=deals`) };
}

function buildDealReadRequest(config, dealId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/deals/${encodeURIComponent(dealId)}?properties=${encodeURIComponent(DEAL_PROPERTIES.join(','))}`) };
}

function buildDealStageUpdateRequest(config, dealId, stageId) {
  return { method: 'PATCH', url: hubspotUrl(config, `/crm/v3/objects/deals/${encodeURIComponent(dealId)}`), body: { properties: { dealstage: stageId } } };
}

function buildContactUpdateRequest(config, contactId, properties) {
  return { method: 'PATCH', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}`), body: { properties } };
}

function buildSequenceEnrollmentRequest(config, { contactId, senderUserId, senderEmail }) {
  return {
    method: 'POST',
    url: hubspotUrl(config, `/automation/v4/sequences/enrollments?userId=${encodeURIComponent(senderUserId)}`),
    body: { contactId: String(contactId), sequenceId: String(config.email.sequenceId), senderEmail },
  };
}

function buildTaskRequest(config, task) {
  const associations = [{ to: { id: task.contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: ASSOCIATION_TYPES.taskToContact }] }];
  if (task.dealId) associations.push({ to: { id: task.dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: ASSOCIATION_TYPES.taskToDeal }] });
  const properties = {
    hs_task_subject: task.subject.slice(0, 250),
    hs_task_body: task.body,
    hs_timestamp: task.dueAt,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'HIGH',
    hs_task_type: 'CALL',
  };
  if (task.ownerId) properties.hubspot_owner_id = task.ownerId;
  return { method: 'POST', url: hubspotUrl(config, '/crm/v3/objects/tasks'), body: { properties, associations } };
}

/** Calendly invitee lookup, used when a no-show payload carries only the invitee URI. */
function buildCalendlyInviteeRequest(config, inviteeUri) {
  if (!inviteeUri || !inviteeUri.startsWith(`${config.calendly.baseUrl}/`)) return null;
  return { method: 'GET', url: inviteeUri };
}

function parseCalendlyInvitee(body) {
  const resource = body && body.resource && typeof body.resource === 'object' ? body.resource : null;
  if (!resource || !resource.email) return { found: false, email: null, firstName: null, scheduledEventUri: null };
  return { found: true, email: String(resource.email).toLowerCase(), firstName: resource.first_name || (resource.name ? String(resource.name).split(' ')[0] : null), scheduledEventUri: resource.event || null };
}

function enforceSandbox(account, config) {
  const portalId = account && account.portalId !== undefined && account.portalId !== null ? String(account.portalId) : null;
  const accountType = account && account.accountType ? String(account.accountType).toUpperCase() : null;
  const uiDomain = account && /^app(?:-[a-z0-9]+)?\.hubspot\.com$/.test(String(account.uiDomain || '')) ? account.uiDomain : 'app.hubspot.com';
  const base = { portalId, accountType, uiDomain };
  if (!config.sandboxMode) return { ok: true, ...base, reason: 'SANDBOX_MODE=false, so production portals are allowed' };
  if (accountType && SANDBOX_ACCOUNT_TYPES.includes(accountType)) return { ok: true, ...base, reason: `account type ${accountType} is a sandbox or test account` };
  if (portalId && !isPlaceholder(config.hubspot.sandboxPortalId) && portalId === config.hubspot.sandboxPortalId) return { ok: true, ...base, reason: 'portal ID matches HUBSPOT_SANDBOX_PORTAL_ID' };
  return { ok: false, ...base, reason: `SANDBOX_MODE=true, but the connected portal (account type ${accountType || 'unknown'}) is not a sandbox or developer test account and does not match HUBSPOT_SANDBOX_PORTAL_ID. I refuse to continue.` };
}

function buildStageIndex(pipelinesBody) {
  const stages = {};
  for (const pipeline of (pipelinesBody && Array.isArray(pipelinesBody.results) ? pipelinesBody.results : [])) {
    for (const stage of pipeline.stages || []) {
      const closed = stage.metadata && String(stage.metadata.isClosed).toLowerCase() === 'true';
      stages[String(stage.id)] = { id: String(stage.id), label: stage.label || String(stage.id), pipelineId: String(pipeline.id), pipelineLabel: pipeline.label || String(pipeline.id), order: Number(stage.displayOrder), closed };
    }
  }
  return stages;
}

function buildOwnerIndex(pages) {
  const byOwnerId = {};
  for (const page of pages) {
    for (const owner of (page && Array.isArray(page.results) ? page.results : [])) {
      byOwnerId[String(owner.id)] = { ownerId: String(owner.id), userId: owner.userId !== undefined && owner.userId !== null ? String(owner.userId) : null, email: owner.email || null, name: [owner.firstName, owner.lastName].filter(Boolean).join(' ') || `Owner ${owner.id}` };
    }
  }
  return byOwnerId;
}

function associationIds(body, type) {
  const block = body && body.associations && body.associations[type];
  return block && Array.isArray(block.results) ? [...new Set(block.results.map((entry) => String(entry.id)))] : [];
}

/** Parses any CRM object response into { found, id, properties, contactIds, dealIds, error }. */
function parseObjectResponse(body) {
  if (body && typeof body === 'object' && body.id !== undefined && body.properties) {
    return { found: true, id: String(body.id), properties: body.properties, contactIds: associationIds(body, 'contacts'), dealIds: associationIds(body, 'deals'), error: null };
  }
  const message = body && typeof body === 'object' ? (typeof body.error === 'object' && body.error ? body.error.message : body.message || body.error) : null;
  return { found: false, id: null, properties: {}, contactIds: [], dealIds: [], error: String(message || 'not_readable').slice(0, 200) };
}

function parseWriteResponse(key, body) {
  const ok = Boolean(body && typeof body === 'object' && !body.error && !(typeof body.code === 'number' && Number(body.status) >= 400) && (body.id !== undefined || body.sid !== undefined));
  return { key, ok, id: ok ? String(body.id ?? body.sid ?? '') : null, error: ok ? null : String((body && (body.message || (body.error && body.error.message) || body.error)) || 'write_failed').slice(0, 200) };
}

function recordUrl(portal, objectTypeId, id) {
  if (!portal || !/^\d+$/.test(String(portal.portalId || ''))) return null;
  return `https://${portal.uiDomain || 'app.hubspot.com'}/contacts/${portal.portalId}/record/${objectTypeId}/${id}`;
}

/* ---------- one-time property setup (scripts/create-properties.js) ---------- */

function buildPropertyDefinitions(config, groupName = 'contactinformation') {
  return [
    {
      name: config.properties.status, label: 'No-show re-engagement status', groupName, type: 'enumeration', fieldType: 'select',
      description: 'Set by the no-show re-engagement pipeline. A HubSpot workflow can trigger on "email_triggered".',
      options: ['email_triggered', 'sms_sent', 'sequence_enrolled', 'skipped_cooldown', 'skipped_no_channel'].map((value, displayOrder) => ({ label: value.replace(/_/g, ' '), value, displayOrder })),
    },
    { name: config.properties.lastReengagedAt, label: 'No-show last re-engaged at', groupName, type: 'datetime', fieldType: 'date', description: 'When the pipeline last re-engaged this contact after a no-show (drives the cooldown).' },
    { name: config.properties.count, label: 'No-show count', groupName, type: 'number', fieldType: 'number', description: 'Meetings this contact missed, as counted by the pipeline.' },
    { name: config.routing.smsConsentProperty, label: 'SMS marketing consent', groupName, type: 'enumeration', fieldType: 'booleancheckbox', description: 'Explicit SMS consent. Only "true" allows re-engagement SMS.', options: [{ label: 'Yes', value: 'true', displayOrder: 0 }, { label: 'No', value: 'false', displayOrder: 1 }] },
  ];
}

// ---- src/core/noshow.js (embedded by scripts/build-workflow.js) ----
/**
 * The no-show engine: meeting status filter, deal stage policy, re-engagement channel router
 * and rep task content. Pure functions; every write is planned here and executed elsewhere.
 */

const DAY_MS = 86400000;

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

/* ---------- 1. Calendly invitee lookups (only when the payload has no email) ---------- */

function planCalendlyLookups(events, config) {
  const tokenReady = config.mode === 'demo' || !isPlaceholder(config.calendly.apiToken);
  return events
    .filter((event) => event.source === 'calendly' && !event.email && event.inviteeUri && tokenReady)
    .map((event) => ({ eventKey: event.eventKey, request: buildCalendlyInviteeRequest(config, event.inviteeUri) }))
    .filter((plan) => plan.request);
}

function applyCalendlyLookups(events, lookups) {
  const byKey = Object.fromEntries(lookups.map((lookup) => [lookup.eventKey, lookup]));
  return events.map((event) => {
    const lookup = byKey[event.eventKey];
    if (!lookup || !lookup.found) return event;
    return { ...event, email: lookup.email, firstName: event.firstName || lookup.firstName };
  });
}

/* ---------- 2. Primary lookups: the meeting (HubSpot) or the contact by email (Calendly) ---------- */

function planPrimaryLookups(events, config) {
  const plans = [];
  for (const event of events) {
    if (event.source === 'hubspot') plans.push({ eventKey: event.eventKey, kind: 'meeting', request: buildMeetingReadRequest(config, event.meetingId) });
    else if (event.email) plans.push({ eventKey: event.eventKey, kind: 'contact', request: buildContactByEmailRequest(config, event.email) });
  }
  return plans;
}

/**
 * The HubSpot Meeting Status Filter. Returns one case per event:
 * { eventKey, source, status: 'no_show' | 'skipped', skipReason, meeting, contactId, contact, dealIds }.
 */
function filterNoShows(events, lookups, config) {
  const byKey = Object.fromEntries(lookups.map((lookup) => [lookup.eventKey, lookup]));
  return events.map((event) => {
    const base = { eventKey: event.eventKey, source: event.source, firstName: event.firstName, meetingTitle: event.meetingTitle, scheduledAt: event.scheduledAt };
    const lookup = byKey[event.eventKey];
    if (event.source === 'calendly' && !event.email) return { ...base, status: 'skipped', skipReason: 'calendly_invitee_email_unknown' };
    if (!lookup || !lookup.found) return { ...base, status: 'skipped', skipReason: event.source === 'calendly' ? 'contact_not_in_hubspot' : 'meeting_not_readable' };
    if (event.source === 'hubspot') {
      const outcome = text(lookup.properties.hs_meeting_outcome).toUpperCase();
      if (!config.hubspot.noShowOutcomes.includes(outcome)) return { ...base, status: 'skipped', skipReason: `outcome_${(outcome || 'empty').toLowerCase()}` };
      if (!lookup.contactIds.length) return { ...base, status: 'skipped', skipReason: 'no_associated_contact' };
      return {
        ...base,
        status: 'no_show',
        meeting: { id: lookup.id, title: text(lookup.properties.hs_meeting_title) || null, startTime: text(lookup.properties.hs_meeting_start_time) || null, ownerId: text(lookup.properties.hubspot_owner_id) || null },
        meetingTitle: text(lookup.properties.hs_meeting_title) || event.meetingTitle,
        scheduledAt: text(lookup.properties.hs_meeting_start_time) || event.scheduledAt,
        contactId: lookup.contactIds[0],
        extraContacts: lookup.contactIds.length - 1,
        contact: null,
        dealIds: lookup.dealIds,
      };
    }
    return { ...base, status: 'no_show', meeting: null, contactId: lookup.id, extraContacts: 0, contact: { id: lookup.id, properties: lookup.properties }, dealIds: lookup.dealIds };
  });
}

/* ---------- 3. Detail reads: contacts (meeting path) and deals ---------- */

function planDetailReads(cases, config) {
  const plans = [];
  const contacts = new Set();
  const deals = new Set();
  for (const entry of cases.filter((item) => item.status === 'no_show')) {
    if (!entry.contact && !contacts.has(entry.contactId)) {
      contacts.add(entry.contactId);
      plans.push({ kind: 'contact', id: entry.contactId, request: buildContactReadRequest(config, entry.contactId) });
    }
    for (const dealId of entry.dealIds.slice(0, config.deals.maxDealsPerContact)) {
      if (deals.has(dealId)) continue;
      deals.add(dealId);
      plans.push({ kind: 'deal', id: dealId, request: buildDealReadRequest(config, dealId) });
    }
  }
  return plans;
}

/* ---------- 4. Deal stage policy ---------- */

function decideDeals(deals, stageIndex, config) {
  const open = deals.filter((deal) => {
    const stage = stageIndex[text(deal.properties.dealstage)];
    return !stage || !stage.closed;
  }).sort((a, b) => (Date.parse(b.properties.createdate) || 0) - (Date.parse(a.properties.createdate) || 0));
  if (!deals.length) return [{ dealId: null, action: 'skip', reason: 'no_associated_deal' }];
  if (!open.length) return [{ dealId: null, action: 'skip', reason: 'no_open_deal' }];
  const selected = config.deals.selection === 'all' ? open : open.slice(0, 1);
  return selected.map((deal) => {
    const current = stageIndex[text(deal.properties.dealstage)] || null;
    const base = { dealId: deal.id, dealName: text(deal.properties.dealname) || `Deal ${deal.id}`, ownerId: text(deal.properties.hubspot_owner_id) || null, fromStage: current ? current.label : text(deal.properties.dealstage) };
    if (!current) return { ...base, action: 'skip', reason: 'unknown_stage' };
    const targetId = config.deals.stageMap[current.pipelineId];
    const target = targetId ? stageIndex[targetId] : null;
    if (!targetId) return { ...base, action: 'skip', reason: 'no_target_stage_for_pipeline' };
    if (!target || target.pipelineId !== current.pipelineId) return { ...base, action: 'skip', reason: 'target_stage_not_in_pipeline' };
    if (current.id === target.id) return { ...base, action: 'skip', reason: 'already_in_no_show_stage', toStage: target.label };
    if (!config.deals.allowBackwardMoves && current.order > target.order) return { ...base, action: 'skip', reason: 'deal_beyond_no_show_stage', toStage: target.label };
    return { ...base, action: 'update', targetStageId: target.id, toStage: target.label };
  });
}

/* ---------- 5. Re-engagement channel router ---------- */

function normalizeSmsNumber(raw, defaultCountryCode) {
  const value = text(raw);
  if (!value) return null;
  const digits = value.replace(/\D/g, '');
  if (value.startsWith('+')) return digits.length >= 8 && digits.length <= 15 ? `+${digits}` : null;
  if (defaultCountryCode === '1' && digits.length === 10) return `+1${digits}`;
  if (digits.startsWith(defaultCountryCode) && digits.length >= 8 && digits.length <= 15) return `+${digits}`;
  return null;
}

function localHour(now, timeZone) {
  const hour = new Intl.DateTimeFormat('en-US', { timeZone, hour: 'numeric', hourCycle: 'h23' }).format(new Date(now));
  return Number(hour) % 24;
}

function renderTemplate(template, values) {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (match, key) => (values[key] === undefined || values[key] === null ? '' : String(values[key]))).replace(/\s{2,}/g, ' ').trim().slice(0, 480);
}

function isTrue(value) {
  return ['true', 'yes', '1'].includes(text(value).toLowerCase());
}

/**
 * Picks the channel(s) for one contact: cooldown first, then CHANNEL_PRIORITY, with SMS needing explicit
 * consent, a usable number, the allowed hours and (in sandbox mode) a test recipient; email needing an
 * address, no opt-out and an email provider.
 */
function routeChannels(contact, config, now, context) {
  const properties = contact.properties;
  const reasons = [];
  const lastAt = Date.parse(text(properties[config.properties.lastReengagedAt]));
  if (config.routing.cooldownDays > 0 && Number.isFinite(lastAt) && now - lastAt < config.routing.cooldownDays * DAY_MS) {
    return { channels: [], status: 'skipped_cooldown', reasons: [`re-engaged ${Math.floor((now - lastAt) / DAY_MS)} day(s) ago (cooldown ${config.routing.cooldownDays} days)`], sms: null };
  }
  const eligible = [];
  let sms = null;
  for (const channel of config.routing.channelPriority) {
    if (channel === 'sms') {
      const number = normalizeSmsNumber(properties.mobilephone || properties.phone, config.sms.defaultCountryCode);
      const hour = localHour(now, config.sms.timeZone);
      if (!smsEnabled(config)) reasons.push('sms: SMS_PROVIDER=none');
      else if (!isTrue(properties[config.routing.smsConsentProperty])) reasons.push(`sms: no explicit consent in ${config.routing.smsConsentProperty}`);
      else if (!number) reasons.push('sms: no usable mobile number');
      else if (hour < config.sms.allowedHours.start || hour >= config.sms.allowedHours.end) reasons.push(`sms: outside allowed hours (${hour}:00 in ${config.sms.timeZone})`);
      else if (config.sandboxMode && isPlaceholder(config.sms.sandboxRecipient)) reasons.push('sms: SANDBOX_MODE is on and SMS_SANDBOX_RECIPIENT is not set');
      else {
        eligible.push('sms');
        sms = {
          to: config.sandboxMode ? config.sms.sandboxRecipient : number,
          originalNumberMasked: maskNumber(number),
          body: renderTemplate(config.sms.template, { firstName: text(properties.firstname) || context.firstName || 'there', rebookUrl: config.rebookUrl, meetingTitle: context.meetingTitle || 'our meeting' }),
        };
      }
    }
    if (channel === 'email') {
      if (config.email.provider === 'none') reasons.push('email: EMAIL_PROVIDER=none');
      else if (!text(properties.email)) reasons.push('email: no email address');
      else if (isTrue(properties[config.routing.emailOptOutProperty])) reasons.push('email: contact opted out of email');
      else eligible.push('email');
    }
  }
  const channels = config.routing.sendBoth ? eligible : eligible.slice(0, 1);
  const status = !channels.length ? 'skipped_no_channel' : channels[0] === 'sms' ? 'sms_sent' : config.email.provider === 'hubspot_sequence' ? 'sequence_enrolled' : 'email_triggered';
  return { channels, status, reasons, sms: channels.includes('sms') ? sms : null };
}

function maskNumber(e164) {
  const digits = text(e164).replace(/\D/g, '');
  return digits.length > 4 ? `+${'*'.repeat(digits.length - 4)}${digits.slice(-4)}` : '****';
}

/* ---------- 6. Cases: everything decided for each no-show ---------- */

function buildCases(filtered, details, stageIndex, owners, portal, config, now) {
  const contacts = Object.fromEntries(details.filter((detail) => detail.kind === 'contact' && detail.found).map((detail) => [detail.id, detail]));
  const deals = Object.fromEntries(details.filter((detail) => detail.kind === 'deal' && detail.found).map((detail) => [detail.id, detail]));
  return filtered.map((entry) => {
    if (entry.status !== 'no_show') return entry;
    const contact = entry.contact || (contacts[entry.contactId] ? { id: entry.contactId, properties: contacts[entry.contactId].properties } : null);
    if (!contact) return { ...entry, status: 'skipped', skipReason: 'contact_not_readable' };
    const properties = contact.properties;
    const name = [text(properties.firstname), text(properties.lastname)].filter(Boolean).join(' ') || text(properties.email) || `Contact ${contact.id}`;
    const dealDecisions = decideDeals(entry.dealIds.slice(0, config.deals.maxDealsPerContact).map((id) => deals[id]).filter(Boolean).map((detail) => ({ id: detail.id, properties: detail.properties })), stageIndex, config);
    const route = routeChannels(contact, config, now, { firstName: entry.firstName, meetingTitle: entry.meetingTitle });
    const primaryDeal = dealDecisions.find((decision) => decision.dealId) || null;
    const ownerId = (entry.meeting && entry.meeting.ownerId) || (primaryDeal && primaryDeal.ownerId) || text(properties.hubspot_owner_id) || (isPlaceholder(config.tasks.fallbackOwnerId) ? null : config.tasks.fallbackOwnerId);
    const owner = ownerId ? owners[ownerId] || null : null;
    const previousCount = Number(text(properties[config.properties.count])) || 0;
    const stamp = { [config.properties.status]: route.status, [config.properties.count]: String(previousCount + 1) };
    if (route.channels.length) stamp[config.properties.lastReengagedAt] = new Date(now).toISOString();
    const dealLine = dealDecisions.map((decision) => (decision.action === 'update' ? `Deal "${decision.dealName}" moved from ${decision.fromStage} to ${decision.toStage}.` : `Deal not moved (${decision.reason.replace(/_/g, ' ')}${decision.dealName ? `: ${decision.dealName}` : ''}).`)).join(' ');
    const channelLine = route.channels.length ? `Automated re-engagement: ${route.channels.join(' + ')}.` : `No automated message (${route.status === 'skipped_cooldown' ? 'cooldown' : 'no eligible channel'}): ${route.reasons.join('; ')}.`;
    const task = config.tasks.enabled ? {
      contactId: contact.id,
      dealId: primaryDeal ? primaryDeal.dealId : null,
      ownerId,
      dueAt: new Date(now + config.tasks.dueHours * 3600000).toISOString(),
      subject: `No-show follow-up: ${name}${entry.meetingTitle ? ` (${entry.meetingTitle})` : ''}`,
      body: [
        `${name} missed ${entry.meetingTitle ? `"${entry.meetingTitle}"` : 'a scheduled meeting'}${entry.scheduledAt ? ` scheduled for ${entry.scheduledAt}` : ''}.`,
        channelLine,
        dealLine,
        isPlaceholder(config.rebookUrl) ? 'Call or email personally to rebook.' : `Rebooking link: ${config.rebookUrl}`,
        entry.extraContacts > 0 ? `Note: ${entry.extraContacts} other attendee(s) on this meeting were not re-engaged automatically.` : '',
      ].filter(Boolean).join('\n'),
    } : null;
    return {
      ...entry,
      contact: { id: contact.id, name, email: text(properties.email) || null, url: recordUrl(portal, '0-1', contact.id) },
      dealDecisions,
      route,
      stamp,
      task,
      ownerName: owner ? owner.name : null,
      sequenceSender: owner && owner.userId && owner.email ? { senderUserId: owner.userId, senderEmail: owner.email } : null,
    };
  });
}

function summarizeCases(cases) {
