  if (!Number.isFinite(number) || (integer && !Number.isInteger(number)) || number < min || number > max) {
    problems.push(`${name} must be ${integer ? 'an integer' : 'a number'} between ${min} and ${max} (received "${raw}")`);
    return fallback;
  }
  return number;
}

function readChoice(raw, fallback, choices, name, problems) {
  const value = String(raw === undefined || raw === null || String(raw).trim() === '' ? fallback : raw).trim().toLowerCase();
  if (!choices.includes(value)) {
    problems.push(`${name} must be one of ${choices.join(', ')} (received "${raw}")`);
    return fallback;
  }
  return value;
}

function readStageMap(raw, problems) {
  if (raw === undefined || raw === null || isPlaceholder(raw)) return {};
  try {
    const parsed = JSON.parse(String(raw));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('must be an object');
    const map = {};
    for (const [pipelineId, stageId] of Object.entries(parsed)) {
      if (isPlaceholder(stageId)) continue;
      map[String(pipelineId)] = String(stageId);
    }
    return map;
  } catch (error) {
    problems.push(`NO_SHOW_DEAL_STAGE_MAP must be JSON like {"default":"YOUR_NO_SHOW_STAGE_ID"} (${error.message})`);
    return {};
  }
}

function readHours(raw, problems) {
  const text = String(raw === undefined || raw === null || String(raw).trim() === '' ? '9-20' : raw).trim();
  const match = text.match(/^(\d{1,2})-(\d{1,2})$/);
  const start = match ? Number(match[1]) : NaN;
  const end = match ? Number(match[2]) : NaN;
  if (!match || start > 23 || end > 24 || start >= end) {
    problems.push(`SMS_ALLOWED_HOURS must look like 9-20 (received "${raw}")`);
    return { start: 9, end: 20 };
  }
  return { start, end };
}

function isValidTimeZone(zone) {
  try { new Intl.DateTimeFormat('en-US', { timeZone: zone }); return true; } catch { return false; }
}

/** Builds runtime configuration from n8n `$env` or `process.env`. options.forceMode pins "demo" or "hubspot". */
function loadNoShowConfig(env = {}, options = {}) {
  const source = env || {};
  const problems = [];
  const read = (name) => {
    const value = source[name];
    return value === undefined || value === null ? undefined : String(value).trim();
  };
  const token = read('HUBSPOT_PRIVATE_APP_TOKEN') || '';
  const smsTimeZone = read('SMS_TIMEZONE') || 'America/New_York';
  if (!isValidTimeZone(smsTimeZone)) problems.push(`SMS_TIMEZONE "${smsTimeZone}" is not a valid IANA time zone`);
  const channelPriority = readList(read('CHANNEL_PRIORITY'));
  const config = {
    mode: options.forceMode || (isPlaceholder(token) ? 'demo' : 'hubspot'),
    dryRun: readBooleanEnv(read('DRY_RUN'), true),
    sandboxMode: readBooleanEnv(read('SANDBOX_MODE'), true),
    hubspot: {
      token,
      baseUrl: (read('HUBSPOT_BASE_URL') || DEFAULT_HUBSPOT_BASE_URL).replace(/\/+$/, ''),
      sandboxPortalId: read('HUBSPOT_SANDBOX_PORTAL_ID') || '',
      noShowOutcomes: (readList(read('NO_SHOW_OUTCOME_VALUES')).length ? readList(read('NO_SHOW_OUTCOME_VALUES')) : ['NO_SHOW']).map((value) => value.toUpperCase()),
    },
    webhook: {
      secret: read('WEBHOOK_SECRET') || '',
      headerName: (read('WEBHOOK_SECRET_HEADER') || 'x-webhook-secret').toLowerCase(),
      calendlySigningKey: read('CALENDLY_WEBHOOK_SIGNING_KEY') || '',
      maxSignatureAgeMinutes: readNumber(read('WEBHOOK_MAX_AGE_MINUTES'), 5, { min: 1, max: 60 }, 'WEBHOOK_MAX_AGE_MINUTES', problems),
      maxEventsPerRequest: readNumber(read('MAX_EVENTS_PER_REQUEST'), 50, { min: 1, max: 200 }, 'MAX_EVENTS_PER_REQUEST', problems),
      dedupeDays: readNumber(read('EVENT_DEDUPE_DAYS'), 7, { min: 1, max: 90 }, 'EVENT_DEDUPE_DAYS', problems),
    },
    calendly: {
      apiToken: read('CALENDLY_API_TOKEN') || '',
      baseUrl: (read('CALENDLY_BASE_URL') || DEFAULT_CALENDLY_BASE_URL).replace(/\/+$/, ''),
    },
    deals: {
      stageMap: readStageMap(read('NO_SHOW_DEAL_STAGE_MAP'), problems),
      selection: readChoice(read('DEAL_SELECTION'), 'most_recent', DEAL_SELECTIONS, 'DEAL_SELECTION', problems),
      allowBackwardMoves: readBooleanEnv(read('ALLOW_BACKWARD_STAGE_MOVES'), false),
      maxDealsPerContact: readNumber(read('MAX_DEALS_PER_EVENT'), 10, { min: 1, max: 50 }, 'MAX_DEALS_PER_EVENT', problems),
    },
    routing: {
      channelPriority: channelPriority.length ? channelPriority.map((entry) => entry.toLowerCase()) : ['sms', 'email'],
      sendBoth: readBooleanEnv(read('SEND_BOTH_CHANNELS'), false),
      cooldownDays: readNumber(read('REENGAGEMENT_COOLDOWN_DAYS'), 7, { min: 0, max: 365 }, 'REENGAGEMENT_COOLDOWN_DAYS', problems),
      smsConsentProperty: read('SMS_CONSENT_PROPERTY') || 'sms_marketing_consent',
      emailOptOutProperty: read('EMAIL_OPT_OUT_PROPERTY') || 'hs_email_optout',
    },
    sms: {
      provider: readChoice(read('SMS_PROVIDER'), 'none', SMS_PROVIDERS, 'SMS_PROVIDER', problems),
      accountSid: read('TWILIO_ACCOUNT_SID') || '',
      authToken: read('TWILIO_AUTH_TOKEN') || '',
      from: read('TWILIO_FROM_NUMBER') || '',
      messagingServiceSid: read('TWILIO_MESSAGING_SERVICE_SID') || '',
      baseUrl: (read('TWILIO_BASE_URL') || DEFAULT_TWILIO_BASE_URL).replace(/\/+$/, ''),
      sandboxRecipient: read('SMS_SANDBOX_RECIPIENT') || '',
      timeZone: smsTimeZone,
      allowedHours: readHours(read('SMS_ALLOWED_HOURS'), problems),
      defaultCountryCode: (read('SMS_DEFAULT_COUNTRY_CODE') || '1').replace(/^\+/, ''),
      template: read('SMS_TEMPLATE') || 'Hi {{firstName}}, sorry we missed each other today. Pick a new time that suits you: {{rebookUrl}} Reply STOP to opt out.',
    },
    email: {
      provider: readChoice(read('EMAIL_PROVIDER'), 'hubspot_workflow', EMAIL_PROVIDERS, 'EMAIL_PROVIDER', problems),
      sequenceId: read('HUBSPOT_SEQUENCE_ID') || '',
    },
    rebookUrl: read('REBOOKING_URL') || '',
    properties: {
      status: read('REENGAGEMENT_STATUS_PROPERTY') || 'no_show_reengagement_status',
      lastReengagedAt: read('REENGAGEMENT_TIMESTAMP_PROPERTY') || 'no_show_last_reengaged_at',
      count: read('NO_SHOW_COUNT_PROPERTY') || 'no_show_count',
    },
    tasks: {
      enabled: readBooleanEnv(read('CREATE_REP_TASKS'), true),
      dueHours: readNumber(read('TASK_DUE_HOURS'), 2, { min: 1, max: 168 }, 'TASK_DUE_HOURS', problems),
      fallbackOwnerId: read('FALLBACK_TASK_OWNER_ID') || '',
    },
    alerts: { webhookUrl: read('ALERT_WEBHOOK_URL') || '' },
    manualTestMeetingIds: readList(read('MANUAL_TEST_MEETING_IDS')),
    nowOverride: read('PIPELINE_NOW') || null,
    problems,
  };
  if (config.nowOverride && !Number.isFinite(Date.parse(config.nowOverride))) problems.push(`PIPELINE_NOW must be an ISO 8601 timestamp (received "${config.nowOverride}")`);
  const unknownChannels = config.routing.channelPriority.filter((channel) => !CHANNELS.includes(channel));
  if (unknownChannels.length) problems.push(`CHANNEL_PRIORITY contains unknown channels: ${unknownChannels.join(', ')} (use sms, email)`);
  return config;
}

function isLiveMode(config) {
  return !config.dryRun && !config.sandboxMode;
}

function resolveNow(config) {
  const parsed = config.nowOverride ? Date.parse(config.nowOverride) : NaN;
  return Number.isFinite(parsed) ? parsed : Date.now();
}

function smsEnabled(config) {
  return config.sms.provider === 'twilio';
}

function alertsEnabled(config) {
  return !isPlaceholder(config.alerts.webhookUrl) && /^https:\/\//.test(config.alerts.webhookUrl);
}

function describeSafety(config) {
  return {
    mode: config.mode,
    dryRun: config.dryRun,
    sandboxMode: config.sandboxMode,
    smsProvider: config.sms.provider,
    emailProvider: config.email.provider,
    writesPossible: config.mode === 'hubspot' && !config.dryRun,
  };
}

/** Returns { errors, warnings }. Any error stops the workflow before it touches HubSpot, Twilio or Calendly. */
function validateNoShowConfig(config) {
  const errors = [...config.problems];
  const warnings = [];
  const live = isLiveMode(config);

  for (const [key, name] of Object.entries(config.properties)) {
    if (!PROPERTY_NAME_PATTERN.test(name)) errors.push(`contact property for ${key} ("${name}") is not a valid HubSpot property name`);
  }
  for (const name of [config.routing.smsConsentProperty, config.routing.emailOptOutProperty]) {
    if (!PROPERTY_NAME_PATTERN.test(name)) errors.push(`"${name}" is not a valid HubSpot property name`);
  }
  if (!isPlaceholder(config.alerts.webhookUrl) && !/^https:\/\//.test(config.alerts.webhookUrl)) errors.push('ALERT_WEBHOOK_URL must use https://');
  if (smsEnabled(config)) {
    if (isPlaceholder(config.sms.accountSid) || isPlaceholder(config.sms.authToken)) errors.push('SMS_PROVIDER=twilio needs TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN (or set SMS_PROVIDER=none)');
    if (isPlaceholder(config.sms.from) && isPlaceholder(config.sms.messagingServiceSid)) errors.push('SMS_PROVIDER=twilio needs TWILIO_FROM_NUMBER or TWILIO_MESSAGING_SERVICE_SID');
    if (isPlaceholder(config.rebookUrl) && config.sms.template.includes('{{rebookUrl}}')) errors.push('SMS_TEMPLATE uses {{rebookUrl}}, so REBOOKING_URL must be set');
    if (!isPlaceholder(config.sms.sandboxRecipient) && !/^\+\d{8,15}$/.test(config.sms.sandboxRecipient)) errors.push('SMS_SANDBOX_RECIPIENT must be an E.164 number such as +15555550100');
  }
  if (!isPlaceholder(config.rebookUrl) && !/^https:\/\//.test(config.rebookUrl)) errors.push('REBOOKING_URL must use https://');
  if (config.email.provider === 'hubspot_sequence' && (isPlaceholder(config.email.sequenceId) || !/^\d+$/.test(config.email.sequenceId))) errors.push('EMAIL_PROVIDER=hubspot_sequence needs a numeric HUBSPOT_SEQUENCE_ID');

  if (config.mode === 'demo') {
    if (live) errors.push('Live mode (DRY_RUN=false and SANDBOX_MODE=false) needs a real HUBSPOT_PRIVATE_APP_TOKEN. Replace the placeholder or turn DRY_RUN back on.');
    warnings.push('HUBSPOT_PRIVATE_APP_TOKEN is a placeholder, so the pipeline runs against bundled fictional records and makes no network calls.');
    return { errors, warnings };
  }

  if (!/^https:\/\//.test(config.hubspot.baseUrl)) errors.push('HUBSPOT_BASE_URL must use https://');
  const hasSecret = !isPlaceholder(config.webhook.secret) && config.webhook.secret.length >= MIN_SECRET_LENGTH;
  const hasCalendly = !isPlaceholder(config.webhook.calendlySigningKey);
  if (!hasSecret && !hasCalendly) errors.push(`Set WEBHOOK_SECRET (at least ${MIN_SECRET_LENGTH} characters, for HubSpot workflow webhooks) and/or CALENDLY_WEBHOOK_SIGNING_KEY`);
  if (!isPlaceholder(config.webhook.secret) && config.webhook.secret.length < MIN_SECRET_LENGTH) errors.push(`WEBHOOK_SECRET must be at least ${MIN_SECRET_LENGTH} characters`);
  if (!isPlaceholder(config.hubspot.sandboxPortalId) && !/^\d+$/.test(config.hubspot.sandboxPortalId)) errors.push('HUBSPOT_SANDBOX_PORTAL_ID must be numeric when set');
  if (!Object.keys(config.deals.stageMap).length) warnings.push('NO_SHOW_DEAL_STAGE_MAP is empty, so deal stages are never changed.');
  if (hasCalendly && isPlaceholder(config.calendly.apiToken)) warnings.push('CALENDLY_API_TOKEN is not set; Calendly no-show events without an invitee email in the payload are skipped.');
  if (config.email.provider === 'none' && !smsEnabled(config)) warnings.push('Both EMAIL_PROVIDER and SMS_PROVIDER are none: only rep tasks are created.');
  if (live && !alertsEnabled(config)) warnings.push('Live mode without ALERT_WEBHOOK_URL: failures are only visible in the n8n execution log.');
  return { errors, warnings };
}

// ---- src/core/hubspot.js (embedded by scripts/build-workflow.js) ----
/**
 * HubSpot and Calendly request builders and parsers. No network access, and no request object
 * carries a token: the n8n HTTP Request nodes add Authorization headers from $env.
 */

const ASSOCIATION_TYPES = Object.freeze({ taskToContact: 204, taskToDeal: 216 });
const MEETING_PROPERTIES = Object.freeze(['hs_meeting_outcome', 'hs_meeting_title', 'hs_meeting_start_time', 'hubspot_owner_id']);
const DEAL_PROPERTIES = Object.freeze(['dealname', 'dealstage', 'pipeline', 'hubspot_owner_id', 'createdate', 'amount']);

function contactProperties(config) {
  return [...new Set(['email', 'firstname', 'lastname', 'mobilephone', 'phone', 'hubspot_owner_id', config.routing.smsConsentProperty, config.routing.emailOptOutProperty, ...Object.values(config.properties)])];
}

function hubspotUrl(config, path) {
  return `${config.hubspot.baseUrl}${path}`;
}

const buildAccountDetailsRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/account-info/v3/details') });
const buildPipelinesRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/crm/v3/pipelines/deals') });
const buildOwnersRequest = (config) => ({ method: 'GET', url: hubspotUrl(config, '/crm/v3/owners?limit=500&archived=false') });

function buildMeetingReadRequest(config, meetingId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/meetings/${encodeURIComponent(meetingId)}?properties=${encodeURIComponent(MEETING_PROPERTIES.join(','))}&associations=contacts,deals`) };
}

function buildContactReadRequest(config, contactId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}?properties=${encodeURIComponent(contactProperties(config).join(','))}&associations=deals`) };
}

function buildContactByEmailRequest(config, email) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(email)}?idProperty=email&properties=${encodeURIComponent(contactProperties(config).join(','))}&associations=deals`) };
}

function buildDealReadRequest(config, dealId) {
  return { method: 'GET', url: hubspotUrl(config, `/crm/v3/objects/deals/${encodeURIComponent(dealId)}?properties=${encodeURIComponent(DEAL_PROPERTIES.join(','))}`) };
}

function buildDealStageUpdateRequest(config, dealId, stageId) {
  return { method: 'PATCH', url: hubspotUrl(config, `/crm/v3/objects/deals/${encodeURIComponent(dealId)}`), body: { properties: { dealstage: stageId } } };
}

function buildContactUpdateRequest(config, contactId, properties) {
  return { method: 'PATCH', url: hubspotUrl(config, `/crm/v3/objects/contacts/${encodeURIComponent(contactId)}`), body: { properties } };
}

function buildSequenceEnrollmentRequest(config, { contactId, senderUserId, senderEmail }) {
  return {
    method: 'POST',
    url: hubspotUrl(config, `/automation/v4/sequences/enrollments?userId=${encodeURIComponent(senderUserId)}`),
    body: { contactId: String(contactId), sequenceId: String(config.email.sequenceId), senderEmail },
  };
}

function buildTaskRequest(config, task) {
  const associations = [{ to: { id: task.contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: ASSOCIATION_TYPES.taskToContact }] }];
  if (task.dealId) associations.push({ to: { id: task.dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: ASSOCIATION_TYPES.taskToDeal }] });
  const properties = {
    hs_task_subject: task.subject.slice(0, 250),
    hs_task_body: task.body,
    hs_timestamp: task.dueAt,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'HIGH',
    hs_task_type: 'CALL',
  };
  if (task.ownerId) properties.hubspot_owner_id = task.ownerId;
  return { method: 'POST', url: hubspotUrl(config, '/crm/v3/objects/tasks'), body: { properties, associations } };
}

/** Calendly invitee lookup, used when a no-show payload carries only the invitee URI. */
function buildCalendlyInviteeRequest(config, inviteeUri) {
  if (!inviteeUri || !inviteeUri.startsWith(`${config.calendly.baseUrl}/`)) return null;
  return { method: 'GET', url: inviteeUri };
}

function parseCalendlyInvitee(body) {
  const resource = body && body.resource && typeof body.resource === 'object' ? body.resource : null;
  if (!resource || !resource.email) return { found: false, email: null, firstName: null, scheduledEventUri: null };
  return { found: true, email: String(resource.email).toLowerCase(), firstName: resource.first_name || (resource.name ? String(resource.name).split(' ')[0] : null), scheduledEventUri: resource.event || null };
}

function enforceSandbox(account, config) {
  const portalId = account && account.portalId !== undefined && account.portalId !== null ? String(account.portalId) : null;
  const accountType = account && account.accountType ? String(account.accountType).toUpperCase() : null;
  const uiDomain = account && /^app(?:-[a-z0-9]+)?\.hubspot\.com$/.test(String(account.uiDomain || '')) ? account.uiDomain : 'app.hubspot.com';
  const base = { portalId, accountType, uiDomain };
  if (!config.sandboxMode) return { ok: true, ...base, reason: 'SANDBOX_MODE=false, so production portals are allowed' };
  if (accountType && SANDBOX_ACCOUNT_TYPES.includes(accountType)) return { ok: true, ...base, reason: `account type ${accountType} is a sandbox or test account` };
  if (portalId && !isPlaceholder(config.hubspot.sandboxPortalId) && portalId === config.hubspot.sandboxPortalId) return { ok: true, ...base, reason: 'portal ID matches HUBSPOT_SANDBOX_PORTAL_ID' };
  return { ok: false, ...base, reason: `SANDBOX_MODE=true, but the connected portal (account type ${accountType || 'unknown'}) is not a sandbox or developer test account and does not match HUBSPOT_SANDBOX_PORTAL_ID. I refuse to continue.` };
}

function buildStageIndex(pipelinesBody) {
  const stages = {};
  for (const pipeline of (pipelinesBody && Array.isArray(pipelinesBody.results) ? pipelinesBody.results : [])) {
    for (const stage of pipeline.stages || []) {
      const closed = stage.metadata && String(stage.metadata.isClosed).toLowerCase() === 'true';
      stages[String(stage.id)] = { id: String(stage.id), label: stage.label || String(stage.id), pipelineId: String(pipeline.id), pipelineLabel: pipeline.label || String(pipeline.id), order: Number(stage.displayOrder), closed };
    }
  }
  return stages;
}

function buildOwnerIndex(pages) {
  const byOwnerId = {};
  for (const page of pages) {
    for (const owner of (page && Array.isArray(page.results) ? page.results : [])) {
      byOwnerId[String(owner.id)] = { ownerId: String(owner.id), userId: owner.userId !== undefined && owner.userId !== null ? String(owner.userId) : null, email: owner.email || null, name: [owner.firstName, owner.lastName].filter(Boolean).join(' ') || `Owner ${owner.id}` };
    }
  }
  return byOwnerId;
}

function associationIds(body, type) {
  const block = body && body.associations && body.associations[type];
  return block && Array.isArray(block.results) ? [...new Set(block.results.map((entry) => String(entry.id)))] : [];
}

/** Parses any CRM object response into { found, id, properties, contactIds, dealIds, error }. */
function parseObjectResponse(body) {
  if (body && typeof body === 'object' && body.id !== undefined && body.properties) {
    return { found: true, id: String(body.id), properties: body.properties, contactIds: associationIds(body, 'contacts'), dealIds: associationIds(body, 'deals'), error: null };
  }
  const message = body && typeof body === 'object' ? (typeof body.error === 'object' && body.error ? body.error.message : body.message || body.error) : null;
  return { found: false, id: null, properties: {}, contactIds: [], dealIds: [], error: String(message || 'not_readable').slice(0, 200) };
}

function parseWriteResponse(key, body) {
  const ok = Boolean(body && typeof body === 'object' && !body.error && !(typeof body.code === 'number' && Number(body.status) >= 400) && (body.id !== undefined || body.sid !== undefined));
  return { key, ok, id: ok ? String(body.id ?? body.sid ?? '') : null, error: ok ? null : String((body && (body.message || (body.error && body.error.message) || body.error)) || 'write_failed').slice(0, 200) };
}

function recordUrl(portal, objectTypeId, id) {
  if (!portal || !/^\d+$/.test(String(portal.portalId || ''))) return null;
  return `https://${portal.uiDomain || 'app.hubspot.com'}/contacts/${portal.portalId}/record/${objectTypeId}/${id}`;
}

/* ---------- one-time property setup (scripts/create-properties.js) ---------- */

function buildPropertyDefinitions(config, groupName = 'contactinformation') {
  return [
    {
      name: config.properties.status, label: 'No-show re-engagement status', groupName, type: 'enumeration', fieldType: 'select',
      description: 'Set by the no-show re-engagement pipeline. A HubSpot workflow can trigger on "email_triggered".',
      options: ['email_triggered', 'sms_sent', 'sequence_enrolled', 'skipped_cooldown', 'skipped_no_channel'].map((value, displayOrder) => ({ label: value.replace(/_/g, ' '), value, displayOrder })),
    },
    { name: config.properties.lastReengagedAt, label: 'No-show last re-engaged at', groupName, type: 'datetime', fieldType: 'date', description: 'When the pipeline last re-engaged this contact after a no-show (drives the cooldown).' },
    { name: config.properties.count, label: 'No-show count', groupName, type: 'number', fieldType: 'number', description: 'Meetings this contact missed, as counted by the pipeline.' },
    { name: config.routing.smsConsentProperty, label: 'SMS marketing consent', groupName, type: 'enumeration', fieldType: 'booleancheckbox', description: 'Explicit SMS consent. Only "true" allows re-engagement SMS.', options: [{ label: 'Yes', value: 'true', displayOrder: 0 }, { label: 'No', value: 'false', displayOrder: 1 }] },
  ];
}

// ---- src/core/actions.js (embedded by scripts/build-workflow.js) ----
/**
 * Write planners for every action the pipeline takes, plus run totals and redacted failure alerts.
 * Every planner returns [] under DRY_RUN, so no write or message can leave a dry run.
 */

/** Twilio Messages API. The account SID stays a {ACCOUNT_SID} token that the n8n node fills from $env. */
function buildTwilioMessageRequest(config, sms) {
  const form = new URLSearchParams();
  form.set('To', sms.to);
  if (config.sms.messagingServiceSid && !/YOUR_/.test(config.sms.messagingServiceSid)) form.set('MessagingServiceSid', config.sms.messagingServiceSid);
  else form.set('From', config.sms.from);
  form.set('Body', sms.body);
  return { method: 'POST', url: `${config.sms.baseUrl}/2010-04-01/Accounts/{ACCOUNT_SID}/Messages.json`, form: form.toString() };
}

const active = (cases) => cases.filter((entry) => entry.status === 'no_show');

function planDealUpdates(cases, config) {
  if (config.dryRun) return [];
  const seen = new Set();
  const plans = [];
  for (const entry of active(cases)) {
    for (const decision of entry.dealDecisions) {
      if (decision.action !== 'update' || seen.has(decision.dealId)) continue;
      seen.add(decision.dealId);
      plans.push({ key: `deal:${decision.dealId}`, request: buildDealStageUpdateRequest(config, decision.dealId, decision.targetStageId) });
    }
  }
  return plans;
}

function planSmsSends(cases, config) {
  if (config.dryRun) return [];
  return active(cases).filter((entry) => entry.route.sms).map((entry) => ({ key: `sms:${entry.eventKey}`, request: buildTwilioMessageRequest(config, entry.route.sms) }));
}

function planSequenceEnrollments(cases, config) {
  if (config.dryRun || config.email.provider !== 'hubspot_sequence') return [];
  return active(cases)
    .filter((entry) => entry.route.channels.includes('email') && entry.sequenceSender)
    .map((entry) => ({ key: `sequence:${entry.eventKey}`, request: buildSequenceEnrollmentRequest(config, { contactId: entry.contact.id, ...entry.sequenceSender }) }));
}

/** Contact stamps record the outcome. With EMAIL_PROVIDER=hubspot_workflow the "email_triggered" stamp starts the email workflow. */
function planContactStamps(cases, config) {
  if (config.dryRun) return [];
  const byContact = {};
  for (const entry of active(cases)) byContact[entry.contact.id] = entry;
  return Object.values(byContact).map((entry) => ({ key: `contact:${entry.contact.id}`, request: buildContactUpdateRequest(config, entry.contact.id, entry.stamp) }));
}

function planTasks(cases, config) {
